                res = [l, r]
                res_len = r - l + 1
            window_counts[s[l]] -= 1
            if s[l] in t_counts and window_counts[s[l]] < t_counts[s[l]]:
                have -= 1
            l += 1
    return s[res[0]:res[1] + 1] if res_len != float('inf') else ''

